	}{
		{"selector", "func f(m M) string { return m.RenderedFrame }", 1},
		{"composite key", "var x = T{RenderedFrame: \"x\"}", 1},
		{"field", "type T struct{ RenderedFrame string }", 1},
		{"another name", "func f(m M) { _ = m.RenderedFrameCount; _ = m.Frame }", 0},
		{"a string or a comment is not a use", "// RenderedFrame\nvar s = \"RenderedFrame\"", 0},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			fset := token.NewFileSet()
			file, err := parser.ParseFile(fset, "v.go", "package v\n"+tt.body, parser.ParseComments)
			if err != nil {
				t.Fatal(err)
			}
			if got := renderedFrameUses(fset, file); len(got) != tt.want {
				t.Errorf("findings = %v, want %d", got, tt.want)
			}
		})
	}
}

// DEVDESK-341: nothing under internal/ui reads the router's styled frame. The
// two remaining mentions, jobs.FrameMsg.RenderedFrame (internal/jobs/message.go)
// and its producer (internal/app/animation.go), are outside internal/ui on
// purpose: step 5 of the plan retires the field, and this guard does not cover
// them.
func TestActivityGuardNoRenderedFrameUnderUI(t *testing.T) {
	scanned := 0
	sourceFiles(t, func(rel string, fset *token.FileSet, file *ast.File) {
		if !strings.HasPrefix(rel, "ui/") {
			return
		}
		scanned++
		for _, f := range renderedFrameUses(fset, file) {
			t.Errorf("%s: %s under internal/ui (DEVDESK-341: a footer shows the activity dot, not the router's frame)", f.Pos, f.What)
		}
	})
	if scanned == 0 {
		t.Fatal("no source file found under internal/ui: the scan reads nothing")
	}
}

// --- Router acceptance -----------------------------------------------------

// dotRouter is the dashboard on screen with one job running. The animation chain
// is stubbed at an instant of phase "on" so no real timer is slept on.
func dotRouter(t *testing.T) *App {
	t.Helper()
	stubAnimationEvery(t, time.UnixMilli(0))
	a := routerAt(t, &bareView{}, 180, 40)
	seedDashboardActivity(t, a)
	if !a.anim.ticking {
		t.Fatal("a running job started no animation chain")
	}
	return a
}

// footerDots counts the running glyph and its hollow phase in the stripped footer.
func footerDots(footer string) (filled, hollow int) {
	s := ansi.Strip(footer)
	return strings.Count(s, indicator.Glyph(indicator.Running, true)), strings.Count(s, indicator.Glyph(indicator.Running, false))
}

func wantDot(t *testing.T, a *App, vt command.ViewType, filled, hollow int) {
	t.Helper()
	f := viewFooter(t, a, vt)
	if gf, gh := footerDots(f); gf != filled || gh != hollow {
		t.Errorf("footer has %d filled and %d hollow dots, want %d and %d: %q", gf, gh, filled, hollow, ansi.Strip(f))
	}
}

func TestFooterActivityDotBlinksWithTheRouterPhase(t *testing.T) {
	a := dotRouter(t)
	tickAt(a, 0) // 0 ms: on
	wantDot(t, a, command.ViewDashboard, 1, 0)
	tickAt(a, 500) // 500 ms: off
	wantDot(t, a, command.ViewDashboard, 0, 1)
	tickAt(a, 1000)
	wantDot(t, a, command.ViewDashboard, 1, 0)
}

func TestFooterActivityDotIsSteadyUnderStaticMotion(t *testing.T) {
	a := dotRouter(t)
	a.setMotionStatic(true)
	for _, ms := range []int64{0, 500, 1000, 1500} {
		tickAt(a, ms)
		wantDot(t, a, command.ViewDashboard, 1, 0)
	}
}

func TestFooterActivityDotFreezesWhenTheTerminalLosesFocus(t *testing.T) {
	a := dotRouter(t)
	tickAt(a, 500) // off phase
	wantDot(t, a, command.ViewDashboard, 0, 1)

	a.Update(tea.BlurMsg{})
	// The tick that was in flight lands after the blur, on an off phase: the
	// router pins the phase on, hands the view that last frame, and renews nothing.
	cmd := tickAt(a, 500)
	wantDot(t, a, command.ViewDashboard, 1, 0)
	if a.anim.ticking {
		t.Error("the animation chain is still alive after a blur")
			return imp.Name.Name
		}
	}
	return ""
}

// retiredMechanisms reports, in a migrated view's file, every retired
// mechanism: AdvanceSpinner, a StatusColumn: key, a frame field, an activity
// glyph literal, and any reference to bubbletea's Tick / Every (under whatever name the file
// imports it): the router's one tick animates every row.
// rel is the file's path relative to internal/; it keys declaredGlyphConstants.
// RenderedFrame is retired too (DEVDESK-341): no footer takes the router's
// styled braille frame any more.
func retiredMechanisms(fset *token.FileSet, file *ast.File, rel string) []finding {
	var out []finding
	report := func(pos token.Pos, what string) {
		out = append(out, finding{Pos: fset.Position(pos), What: what})
	}
	tea := bubbleTeaName(file)
	selectors := map[*ast.Ident]bool{} // identifiers seen as the Sel of a selector
	// reportTick flags any reference to bubbletea's Tick / Every, called or not
	// (`var tick = tea.Tick` is as much a tick as `tea.Tick(...)`).
	reportTick := func(pos token.Pos, name string) {
		if name == "Tick" || name == "Every" {
			report(pos, "reference to bubbletea's "+name+" (a view's rows are animated by the router's tick)")
		}
	}
	isFrame := func(name string) bool {
		return name == "Frame" || name == "frame" || name == "SpinnerFrame" || name == renderedFrameName
	}
	visit := func() func(ast.Node) bool {
		body string
		want int
		at   string // "line:column" of the first finding, when want > 0
	}{
		{"tea.Tick", "", "func f() { _ = tea.Tick(0, nil) }", 1, "4:16"},
		{"tea.Every", "", "func f() { _ = tea.Every(0, nil) }", 1, "4:16"},
		{"spinner.Tick is not a view tick", "", "func f() { _ = spinner.Tick }\nfunc g() { _ = spinner.Tick() }", 0, ""},
		{"tick in any function", "", "func g() { _ = tea.Tick(0, nil) }", 1, "4:16"},
		{"AdvanceSpinner", "", "func f(t T) { t.AdvanceSpinner() }", 1, "4:15"},
		{"glyph literal", "", "var g = \"\u25cf\"", 1, "4:9"},
		{"StatusColumn key", "", "var x = T{StatusColumn: 1}", 1, "4:11"},
		{"clean", "", "func f() {}", 0, ""},
		{"RenderedFrame selector", "", "func f(m M) { _ = m.RenderedFrame }", 1, "4:21"},
		{"RenderedFrame key", "", "var x = T{RenderedFrame: \"\"}", 1, "4:11"},
		{"a name that merely starts with RenderedFrame", "", "func f(m M) { _ = m.RenderedFrameCount }", 0, ""},
		{"aliased import", bt, "func f() { _ = bt.Tick(0, nil) }", 1, "4:16"},
		{"dot import", dot, "func f() { _ = Tick(0, nil) }", 1, "4:16"},
		{"dot import, bare reference", dot, "var tick = Every", 1, "4:12"},
		{"package variable holding tea.Tick", "", "var tick = tea.Tick", 1, "4:12"},
		{"tick in a method", "", "func (m M) f() { _ = tea.Tick(0, nil) }", 1, "4:22"},
		{"non-bubbletea package named tea", other, "func f() { _ = tea.Tick(0, nil) }", 0, ""},
		for _, prefix := range []string{"jobs/", "app/", "ui/"} {
			if len(rel) >= len(prefix) && rel[:len(prefix)] == prefix {
				scanned[prefix] = true
			}
		}
		for _, f := range frameFieldUses(fset, file) {
			t.Errorf("%s: %s (DEVDESK-341: jobs.FrameMsg carries the blink phase only)", f.Pos, f.What)
		}
	})
	for _, p := range []string{"jobs/", "app/", "ui/"} {
		if !scanned[p] {
			t.Errorf("no source file scanned under internal/%s: the scan reads nothing", p)
		}
	}
}
